-- Speglar det som lades på databasen 2026-09-15 via apply_migration i tre delar:
--   c85_order_code_from_catalogue_part_01  (backup, schema, familj, parametrar)
--   c85_order_code_from_catalogue_part_02  (värdelista, regler 1–20)
--   c85_order_code_from_catalogue_part_03  (regler 21–40, dokumentkarta, produktspecar)
-- Fingeravtryck efter körning, identiska med modellen (scripts/fingerprint-rules.ts c85):
--   regler  40   md5 1af8bacc4aa4b0c2d4132f6cd1b56107   villkor eef7fb0f1b75204167489df1f97f158e
--   värden  70   md5 bcfe46245f1bb85c316aa45e76fd0df0
--   schema       md5 85a98f67f2ffae80ed5626f79946ec88
-- Verifierat live: /sv/configurator/c85 bygger CD85N20-40CJLV-B-M9BWS (katalogens
-- exempel, sida 6) och stoppar M9BW på skena A vid ø20.
--
-- C85: beställnyckeln enligt SMC ISO Standards Air Cylinder C85 Series.
-- GENERERAD ur src/lib/catalog/c85.ts -- redigera inte för hand.
--
-- Rättar familjen c85, som hade mallen 'C85-{bore_mm}-{stroke_mm}-{cushioning}{sensing}'.
-- SMC:s kod är C{magnet}85{gavel}{ø}-{slag}{dämpning}{bälg}{fäste}{tillbehör}-{givarfäste}-{givare}…,
-- t.ex. CD85N20-40CJLV-B-M9BWS (sida 6). Gaveltyp, bälg, fäste, tillbehör
-- och givarfäste fanns inte alls.
--
-- SMC-C85N32 och SMC-C85N40 finns inte (ISO 6432 slutar vid ø25) och
-- avaktiveras. SMC-C85N16–N25 får katalogens slag och temperatur.

begin;

create schema if not exists backup;
create table if not exists backup.c85_before_20260915 as
  select 'param' as sort, p.id::text as id, p.param_key as k, p.label as v
  from configurator_params p join configurator_families f on f.id = p.family_id
  where f.slug = 'c85'
  union all
  select 'value', v.id::text, v.code, v.label
  from configurator_param_values v
  join configurator_params p on p.id = v.param_id
  join configurator_families f on f.id = p.family_id
  where f.slug = 'c85'
  union all
  select 'family', f.id::text, f.slug, coalesce(f.order_code_template, '')
  from configurator_families f where f.slug = 'c85';

insert into config_schemas (schema_id, schema_json, title_sv, title_en, category_slug)
values ('SCHEMA-C85-V1', '{"version":"1.0","steps":[{"id":"bore","step":1,"title_sv":"Kolvdiameter","title_en":"Bore size","required":true,"type":"single_select","options":[{"v":"8","label":"ø8 mm"},{"v":"10","label":"ø10 mm"},{"v":"12","label":"ø12 mm"},{"v":"16","label":"ø16 mm"},{"v":"20","label":"ø20 mm"},{"v":"25","label":"ø25 mm"}]},{"id":"cover","step":2,"title_sv":"Gaveltyp","title_en":"Head cover type","required":true,"type":"single_select","options":[{"v":"N","label":"Basgavel med integrerat gaffelfäste"},{"v":"E","label":"Dubbel ände utan nav (boss-cut)"},{"v":"F","label":"Boss-cut/basgavel"},{"v":"Y","label":"Gavel med axiell anslutning"}]},{"id":"stroke_mm","step":3,"title_sv":"Slaglängd","title_en":"Cylinder stroke","required":true,"type":"numeric","min":1,"max":1000,"unit":"mm"},{"id":"magnet","step":4,"title_sv":"Inbyggd magnet","title_en":"Built-in magnet","required":false,"type":"single_select","options":[{"v":"D","label":"Inbyggd magnet för givare (CD85)"}]},{"id":"cushion","step":5,"title_sv":"Dämpning","title_en":"Cushion","required":false,"type":"single_select","options":[{"v":"C","label":"Luftdämpning (ej ø8, bara gavel N, slag ≥ 25 mm)"}]},{"id":"boot","step":6,"title_sv":"Kolvstångsbälg","title_en":"Rod boot","required":false,"type":"single_select","options":[{"v":"J","label":"Bälg i nylon (ø20, ø25)"},{"v":"K","label":"Värmebeständig bälg (ø20, ø25)"}]},{"id":"bracket","step":7,"title_sv":"Fäste","title_en":"Mounting bracket","required":false,"type":"single_select","options":[{"v":"L","label":"Enkelt fotfäste"},{"v":"M","label":"Dubbelt fotfäste"},{"v":"G","label":"Fläns"},{"v":"U","label":"Tappfäste"},{"v":"N","label":"Gaffelfäste"}]},{"id":"accessory","step":8,"title_sv":"Tillbehör på kolvstången","title_en":"Accessory","required":false,"type":"single_select","options":[{"v":"V","label":"Kolvstångsände (rod end)"},{"v":"W","label":"Dubbelt knäled"}]},{"id":"switch_mount","step":9,"title_sv":"Givarfäste","title_en":"Auto switch mounting type","required":false,"type":"single_select","options":[{"v":"A","label":"Givarfäste för skena (rail)"},{"v":"B","label":"Givarfäste för band"}]},{"id":"switch","step":10,"title_sv":"Magnetgivare","title_en":"Auto switch","required":false,"type":"single_select","options":[{"v":"M9N","label":"D-M9N, 3-tråd NPN, rak"},{"v":"M9P","label":"D-M9P, 3-tråd PNP, rak"},{"v":"M9B","label":"D-M9B, 2-tråd, rak"},{"v":"M9NV","label":"D-M9NV, 3-tråd NPN, vinklad"},{"v":"M9PV","label":"D-M9PV, 3-tråd PNP, vinklad"},{"v":"M9BV","label":"D-M9BV, 2-tråd, vinklad"},{"v":"H7C","label":"D-H7C, 2-tråd, kontakt (band)"},{"v":"J79C","label":"D-J79C, 2-tråd, kontakt (skena)"},{"v":"M9NW","label":"D-M9NW, NPN, tvåfärgsindikering, rak"},{"v":"M9PW","label":"D-M9PW, PNP, tvåfärgsindikering, rak"},{"v":"M9BW","label":"D-M9BW, 2-tråd, tvåfärgsindikering, rak"},{"v":"M9NWV","label":"D-M9NWV, NPN, tvåfärgsindikering, vinklad"},{"v":"M9PWV","label":"D-M9PWV, PNP, tvåfärgsindikering, vinklad"},{"v":"M9BWV","label":"D-M9BWV, 2-tråd, tvåfärgsindikering, vinklad"},{"v":"M9NA","label":"D-M9NA, NPN, vattentät, rak"},{"v":"M9PA","label":"D-M9PA, PNP, vattentät, rak"},{"v":"M9BA","label":"D-M9BA, 2-tråd, vattentät, rak"},{"v":"M9NAV","label":"D-M9NAV, NPN, vattentät, vinklad"},{"v":"M9PAV","label":"D-M9PAV, PNP, vattentät, vinklad"},{"v":"M9BAV","label":"D-M9BAV, 2-tråd, vattentät, vinklad"},{"v":"H7NF","label":"D-H7NF, 4-tråd NPN, diagnostikutgång (band)"},{"v":"F79F","label":"D-F79F, 4-tråd NPN, diagnostikutgång (skena)"},{"v":"A96","label":"D-A96, reed 3-tråd, rak (ø16–25)"},{"v":"A96V","label":"D-A96V, reed 3-tråd, vinklad (ø16–25)"},{"v":"A72","label":"D-A72, reed 200 V (band)"},{"v":"A72H","label":"D-A72H, reed 200 V (skena)"},{"v":"A93","label":"D-A93, reed 2-tråd, rak (ø16–25)"},{"v":"A93V","label":"D-A93V, reed 2-tråd, vinklad (ø16–25)"},{"v":"A90","label":"D-A90, reed utan indikering, rak (ø16–25)"},{"v":"A90V","label":"D-A90V, reed utan indikering, vinklad (ø16–25)"},{"v":"C73C","label":"D-C73C, reed kontakt (band)"},{"v":"A73C","label":"D-A73C, reed kontakt (skena)"},{"v":"C80C","label":"D-C80C, reed kontakt utan indikering (band)"},{"v":"A80C","label":"D-A80C, reed kontakt utan indikering (skena)"},{"v":"A79W","label":"D-A79W, reed tvåfärgsindikering (skena, ø16–25)"}]},{"id":"lead","step":11,"title_sv":"Givarens kabellängd","title_en":"Lead wire length","required":false,"type":"single_select","options":[{"v":"M","label":"1 m kabel"},{"v":"L","label":"3 m kabel"},{"v":"Z","label":"5 m kabel"},{"v":"N","label":"Utan kabel (kontaktgivare)"}]},{"id":"count","step":12,"title_sv":"Antal givare","title_en":"Number of auto switches","required":false,"type":"single_select","options":[{"v":"S","label":"1 givare (standard är 2)"}]},{"id":"mto","step":13,"title_sv":"Specialutförande","title_en":"Made to order","required":false,"type":"single_select","options":[{"v":"XA","label":"-XA Ändrad kolvstångsände"},{"v":"XB6","label":"-XB6 Värmebeständig –10…150 °C (gummidämpning ø10–25, utan tillbehör)"},{"v":"XB7","label":"-XB7 Köldbeständig –40…70 °C (gummidämpning ø20–25, utan tillbehör)"},{"v":"XB9","label":"-XB9 Låg hastighet 10–50 mm/s (gummidämpning ø20–25)"},{"v":"XC4","label":"-XC4 Kraftig avstrykare (gummidämpning ø20–25)"},{"v":"XC6","label":"-XC6 Rostfritt utförande"},{"v":"X2018","label":"-X2018 Slag utöver standardområdet"}]}]}'::jsonb,
        'SMC C85 rundcylinder ISO 6432', 'SMC C85 ISO 6432 round cylinder', 'cylinder')
on conflict (schema_id) do update set
  schema_json = excluded.schema_json,
  title_sv = excluded.title_sv,
  title_en = excluded.title_en;

update configurator_families set
  title = 'Rundcylinder ISO 6432 ø8–25, dubbelverkande enkel kolvstång',
  description = 'SMC C85 ISO 6432 round cylinder, double acting single rod, ø8–25 mm, standard strokes up to 300 mm.',
  stroke_min_mm = 1,
  stroke_max_mm = 1000,
  order_code_template = 'C{magnet}85{cover}{bore}-{stroke_mm}{cushion}{boot}{bracket}{accessory}-{switch_mount}-{switch}{lead}{count}-{mto}',
  rules_schema_id = 'SCHEMA-C85-V1'
where slug = 'c85';


delete from configurator_param_values v using configurator_params p, configurator_families f
  where v.param_id = p.id and p.family_id = f.id and f.slug = 'c85';
delete from configurator_params p using configurator_families f
  where p.family_id = f.id and f.slug = 'c85';

insert into configurator_params (family_id, param_key, label, param_type, sort_order, required, min_value, max_value, show_code)
select f.id, r.param_key, r.label, r.param_type, r.sort_order, r.required, r.min_value, r.max_value, true
from configurator_families f,
     jsonb_to_recordset('[{"param_key":"bore","label":"Kolvdiameter","param_type":"select","sort_order":1,"required":true,"min_value":null,"max_value":null},{"param_key":"cover","label":"Gaveltyp","param_type":"select","sort_order":2,"required":true,"min_value":null,"max_value":null},{"param_key":"stroke_mm","label":"Slaglängd","param_type":"number","sort_order":3,"required":true,"min_value":1,"max_value":1000},{"param_key":"magnet","label":"Inbyggd magnet","param_type":"select","sort_order":4,"required":false,"min_value":null,"max_value":null},{"param_key":"cushion","label":"Dämpning","param_type":"select","sort_order":5,"required":false,"min_value":null,"max_value":null},{"param_key":"boot","label":"Kolvstångsbälg","param_type":"select","sort_order":6,"required":false,"min_value":null,"max_value":null},{"param_key":"bracket","label":"Fäste","param_type":"select","sort_order":7,"required":false,"min_value":null,"max_value":null},{"param_key":"accessory","label":"Tillbehör på kolvstången","param_type":"select","sort_order":8,"required":false,"min_value":null,"max_value":null},{"param_key":"switch_mount","label":"Givarfäste","param_type":"select","sort_order":9,"required":false,"min_value":null,"max_value":null},{"param_key":"switch","label":"Magnetgivare","param_type":"select","sort_order":10,"required":false,"min_value":null,"max_value":null},{"param_key":"lead","label":"Givarens kabellängd","param_type":"select","sort_order":11,"required":false,"min_value":null,"max_value":null},{"param_key":"count","label":"Antal givare","param_type":"select","sort_order":12,"required":false,"min_value":null,"max_value":null},{"param_key":"mto","label":"Specialutförande","param_type":"select","sort_order":13,"required":false,"min_value":null,"max_value":null}]'::jsonb)
       as r(param_key text, label text, param_type text, sort_order int, required boolean,
            min_value numeric, max_value numeric)
where f.slug = 'c85';

