,{"param_key":"switch","code":"M9B","label":"D-M9B, 2-tråd, rak","sort_order":2},{"param_key":"switch","code":"M9NV","label":"D-M9NV, 3-tråd NPN, vinklad","sort_order":3},{"param_key":"switch","code":"M9PV","label":"D-M9PV, 3-tråd PNP, vinklad","sort_order":4},{"param_key":"switch","code":"M9BV","label":"D-M9BV, 2-tråd, vinklad","sort_order":5},{"param_key":"switch","code":"H7C","label":"D-H7C, 2-tråd, kontakt (band)","sort_order":6},{"param_key":"switch","code":"J79C","label":"D-J79C, 2-tråd, kontakt (skena)","sort_order":7},{"param_key":"switch","code":"M9NW","label":"D-M9NW, NPN, tvåfärgsindikering, rak","sort_order":8},{"param_key":"switch","code":"M9PW","label":"D-M9PW, PNP, tvåfärgsindikering, rak","sort_order":9},{"param_key":"switch","code":"M9BW","label":"D-M9BW, 2-tråd, tvåfärgsindikering, rak","sort_order":10},{"param_key":"switch","code":"M9NWV","label":"D-M9NWV, NPN, tvåfärgsindikering, vinklad","sort_order":11},{"param_key":"switch","code":"M9PWV","label":"D-M9PWV, PNP, tvåfärgsindikering, vinklad","sort_order":12},{"param_key":"switch","code":"M9BWV","label":"D-M9BWV, 2-tråd, tvåfärgsindikering, vinklad","sort_order":13},{"param_key":"switch","code":"M9NA","label":"D-M9NA, NPN, vattentät, rak","sort_order":14},{"param_key":"switch","code":"M9PA","label":"D-M9PA, PNP, vattentät, rak","sort_order":15},{"param_key":"switch","code":"M9BA","label":"D-M9BA, 2-tråd, vattentät, rak","sort_order":16},{"param_key":"switch","code":"M9NAV","label":"D-M9NAV, NPN, vattentät, vinklad","sort_order":17},{"param_key":"switch","code":"M9PAV","label":"D-M9PAV, PNP, vattentät, vinklad","sort_order":18},{"param_key":"switch","code":"M9BAV","label":"D-M9BAV, 2-tråd, vattentät, vinklad","sort_order":19},{"param_key":"switch","code":"H7NF","label":"D-H7NF, 4-tråd NPN, diagnostikutgång (band)","sort_order":20},{"param_key":"switch","code":"F79F","label":"D-F79F, 4-tråd NPN, diagnostikutgång (skena)","sort_order":21},{"param_key":"switch","code":"A96","label":"D-A96, reed 3-trå