delete from config_rules where schema_id = 'SCHEMA-C85-V1';


insert into config_rules (schema_id, severity, if_json, message_sv, message_en, goto_step)
select 'SCHEMA-C85-V1', r->>'severity', r->'if_json',
       r->>'message_sv', r->>'message_en', r->>'goto_step'
from jsonb_array_elements('[{"severity":"error","if_json":{"and":[{"==":[{"var":"cushion"},"C"]},{"in":[{"var":"bore"},["8"]]}]},"message_sv":"Luftdämpning finns inte för ø8 (sida 6).","message_en":"Air cushion is not available for ø8 (page 6).","goto_step":"c85-cushion"},{"severity":"error","if_json":{"and":[{"==":[{"var":"cushion"},"C"]},{"in":[{"var":"cover"},["E","F","Y"]]}]},"message_sv":"Luftdämpning finns bara med basgaveln N, inte E, F och Y (sida 6).","message_en":"Air cushion exists only with the basic head cover N, not E, F and Y (page 6).","goto_step":"c85-cushion"},{"severity":"error","if_json":{"and":[{"==":[{"var":"cushion"},"C"]},{">":[{"var":"stroke_mm"},0]},{"<":[{"var":"stroke_mm"},25]}]},"message_sv":"Med luftdämpning är minsta slag 25 mm (sida 7, not 4).","message_en":"With air cushion the minimum stroke is 25 mm (page 7, note 4).","goto_step":"c85-stroke_mm"},{"severity":"error","if_json":{"and":[{"in":[{"var":"boot"},["J","K"]]},{"in":[{"var":"bore"},["8","10","12","16"]]}]},"message_sv":"Bälg finns bara för ø20 och 25.","message_en":"The rod boot exists only for ø20 and 25.","goto_step":"c85-boot"},{"severity":"error","if_json":{"and":[{"==":[{"var":"cover"},"E"]},{"in":[{"var":"bracket"},["N"]]}]},"message_sv":"Gavel E tar fäste L, M, G eller U, inte N (sida 6).","message_en":"Head cover E takes bracket L, M, G or U, not N (page 6).","goto_step":"c85-bracket"},{"severity":"error","if_json":{"and":[{"==":[{"var":"cover"},"F"]},{"in":[{"var":"bracket"},["M","N"]]}]},"message_sv":"Gavel F tar fäste L, G eller U, inte M och N (sida 6).","message_en":"Head cover F takes bracket L, G or U, not M and N (page 6).","goto_step":"c85-bracket"},{"severity":"error","if_json":{"and":[{"==":[{"var":"cover"},"Y"]},{"in":[{"var":"bracket"},["M","N"]]}]},"message_sv":"Gavel Y tar fäste L, G eller U, inte M och N (sida 6).","message_en":"Head cover Y takes bracket L, G or U, not M and N (page 6).","goto_step":"c85-bracket"},{"severity":"error","if_json":{"and"