insert into knowledge_doc_families (source_file, family_slug, doc_title)
values ('smc-kat-c85.pdf', 'c85', 'SMC — SMC ISO Standards Air Cylinder C85 Series')
on conflict (source_file, family_slug) do update set doc_title = excluded.doc_title;


update product_specs s set value = '200 mm (standard); upp till 400 mm på begäran'
from products p where s.product_id = p.id and p.sku = 'SMC-C85N16' and s.key = 'stroke_mm';

update product_specs s set value = '-20…+80 (utan givare), -10…+60 (med givare)'
from products p where s.product_id = p.id and p.sku = 'SMC-C85N16' and s.key = 'temp_range';

insert into product_specs (product_id, key, value)
select p.id, x.key, x.value
from products p
cross join lateral (values
  ('standard_strokes_mm', '10, 25, 40, 50, 80, 100, 125, 160, 200'),
  ('min_pressure_mpa', '0.05'),
  ('order_code_example', 'C85N16-200'),
  ('catalogue', 'SMC C85/C75, How to Order sida 6, data sida 7')
) as x(key, value)
where p.sku = 'SMC-C85N16'
  and not exists (select 1 from product_specs y where y.product_id = p.id and y.key = x.key);


update product_specs s set value = '300 mm (standard); upp till 1000 mm på begäran'
from products p where s.product_id = p.id and p.sku = 'SMC-C85N20' and s.key = 'stroke_mm';

update product_specs s set value = '-20…+80 (utan givare), -10…+60 (med givare)'
from products p where s.product_id = p.id and p.sku = 'SMC-C85N20' and s.key = 'temp_range';

insert into product_specs (product_id, key, value)
select p.id, x.key, x.value
from products p
cross join lateral (values
  ('standard_strokes_mm', '10, 25, 40, 50, 80, 100, 125, 160, 200, 250, 300'),
  ('min_pressure_mpa', '0.05'),
  ('order_code_example', 'C85N20-300'),
  ('catalogue', 'SMC C85/C75, How to Order sida 6, data sida 7')
) as x(key, value)
where p.sku = 'SMC-C85N20'
  and not exists (select 1 from product_specs y where y.product_id = p.id and y.key = x.key);


update product_specs s set value = '300 mm (standard); upp till 1000 mm på begäran'
from products p where s.product_id = p.id and p.sku = 'SMC-C85N25' and s.key = 'stroke_mm';

update product_specs s set value = '-20…+80 (utan givare), -10…+60 (med givare)'
from products p where s.product_id = p.id and p.sku = 'SMC-C85N25' and s.key = 'temp_range';

insert into product_specs (product_id, key, value)
select p.id, x.key, x.value
from products p
cross join lateral (values
  ('standard_strokes_mm', '10, 25, 40, 50, 80, 100, 125, 160, 200, 250, 300'),
  ('min_pressure_mpa', '0.05'),
  ('order_code_example', 'C85N25-300'),
  ('catalogue', 'SMC C85/C75, How to Order sida 6, data sida 7')
) as x(key, value)
where p.sku = 'SMC-C85N25'
